package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders a formatted ledger for the given entries.
//
// Refactoring log (per .docs/instructions.md):
//  1. Validate currency and locale up front instead of relying on a recursive
//     call with a dummy entry for empty input.
//  2. Replace the hand-rolled bubble sort with sort.Slice using a plain
//     less function (date, then description, then change).
//  3. Replace the goroutine-per-entry channel fan-out with a simple sequential
//     loop building into a strings.Builder.
//  4. Extract the date, description, and amount formatting into small helpers.
//  5. Replace the duplicated thousands-grouping logic with a single helper.

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if _, err := currencySymbol(currency); err != nil {
		return "", err
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errors.New("invalid locale")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(headerLine(locale))
	for _, entry := range sorted {
		line, err := formatLine(locale, currency, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}
```

